mapper.select:
SELECT COUNT(1)
FROM order_form_item i
JOIN order_form f ON f.id = i.form_id AND f.deleted = 0 AND f.status = 'reviewed'
LEFT JOIN user_semester_profile p ON p.user_id = f.teacher_id AND p.semester_id = f.semester_id AND p.deleted = 0
WHERE i.deleted = 0 AND f.semester_id = #{semesterId}
 AND p.college_id = #{collegeId}
